import { NavLink } from 'react-router-dom';

const nav = [
  { to: '/analytics', icon: '📊', label: 'Analytics' },
  { to: '/chat',      icon: '💬', label: 'Chat', badge: 3 },
  { to: '/upload',    icon: '📁', label: 'Upload Docs' },
  { to: '/settings',  icon: '⚙️', label: 'Settings' },
];

export default function Sidebar() {
  return (
    <div style={{
      width: 220, minWidth: 220,
      background: 'var(--bg2)',
      borderRight: '1px solid var(--border)',
      display: 'flex', flexDirection: 'column',
      position: 'relative', zIndex: 10
    }}>
      {/* Logo */}
      <div style={{ padding: '20px 20px 16px', borderBottom: '1px solid var(--border)' }}>
        <div style={{
          fontFamily: 'var(--mono)', fontSize: '1.3rem', fontWeight: 700,
          background: 'linear-gradient(135deg, #3b82f6, #06b6d4)',
          WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent'
        }}>ARIA</div>
        <div style={{ fontSize: '0.6rem', color: 'var(--text3)', marginTop: 2, letterSpacing: '0.15em', textTransform: 'uppercase' }}>
          Dashboard v2.0
        </div>
      </div>

      {/* Nav */}
      <nav style={{ flex: 1, padding: '12px 10px', display: 'flex', flexDirection: 'column', gap: 2 }}>
        <div style={{ fontSize: '0.55rem', color: 'var(--text3)', letterSpacing: '0.2em', textTransform: 'uppercase', padding: '8px 10px 4px', fontFamily: 'var(--mono)' }}>
          Main
        </div>
        {nav.map(({ to, icon, label, badge }) => (
          <NavLink key={to} to={to} style={({ isActive }) => ({
            display: 'flex', alignItems: 'center', gap: 10,
            padding: '9px 12px', borderRadius: 8,
            fontSize: '0.82rem', fontWeight: 500,
            textDecoration: 'none',
            border: '1px solid',
            borderColor: isActive ? 'rgba(59,130,246,0.25)' : 'transparent',
            background: isActive ? 'rgba(59,130,246,0.12)' : 'transparent',
            color: isActive ? 'var(--accent)' : 'var(--text2)',
            transition: 'all 0.2s',
          })}>
            <span style={{ fontSize: '1rem', width: 18, textAlign: 'center' }}>{icon}</span>
            <span style={{ flex: 1 }}>{label}</span>
            {badge && (
              <span style={{
                background: 'var(--accent)', color: '#fff',
                fontSize: '0.55rem', padding: '1px 6px',
                borderRadius: 20, fontFamily: 'var(--mono)'
              }}>{badge}</span>
            )}
          </NavLink>
        ))}
      </nav>

      {/* User */}
      <div style={{ padding: 14, borderTop: '1px solid var(--border)' }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 10,
          padding: '8px 10px', borderRadius: 8,
          background: 'var(--surface)', border: '1px solid var(--border)'
        }}>
          <div style={{
            width: 30, height: 30, borderRadius: '50%',
            background: 'linear-gradient(135deg, #3b82f6, #8b5cf6)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            fontSize: '0.75rem', fontWeight: 700, color: '#fff', flexShrink: 0
          }}>KB</div>
          <div>
            <div style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--text)' }}>Keshav B.</div>
            <div style={{ fontSize: '0.58rem', color: 'var(--text3)' }}>Administrator</div>
          </div>
        </div>
      </div>
    </div>
  );
}
